#!/bin/bash
# agy-file-change-hook.sh - CodeAgentSwarm Antigravity PreToolUse file-change tracker.
# Auto-generated by CodeAgentSwarm - Do not edit manually.
# Post to THIS instance's webhook port (injected into the PTY env by CodeAgentSwarm);
# the fallbacks keep the legacy dev-first (45783) / prod (45782) behaviour for older builds.
WEBHOOK_PORT_DEV="${CODEAGENTSWARM_WEBHOOK_PORT:-45783}"
WEBHOOK_PORT_PROD="${CODEAGENTSWARM_WEBHOOK_PORT:-45782}"
# The plugin loads in every agy session on the machine. Outside a CodeAgentSwarm
# terminal (no quadrant env) stay silent — posting as terminal 0 paints phantom
# file-change badges inside the app.
[ -z "${CODEAGENTSWARM_CURRENT_QUADRANT:-}" ] && exit 0
TERM_ID="$CODEAGENTSWARM_CURRENT_QUADRANT"

TMP=$(mktemp) || exit 0
# Bound both disk use and a producer that never closes stdin.
head -c 1048577 > "$TMP" <&0 &
input_pid=$!
(sleep 5 & timer_sleep=$!
trap '[ -z "$timer_sleep" ] || kill "$timer_sleep" 2>/dev/null' EXIT
wait "$timer_sleep"; timer_sleep=; kill "$input_pid" 2>/dev/null) &
input_timer=$!
trap '[ -z "$input_pid" ] || kill "$input_pid" 2>/dev/null; [ -z "$input_timer" ] || kill "$input_timer" 2>/dev/null; rm -f "$TMP"' EXIT
wait "$input_pid"
input_result=$?
input_pid=
kill "$input_timer" 2>/dev/null
wait "$input_timer" 2>/dev/null
input_timer=
[ "$input_result" -eq 0 ] || exit 0
[ "$(wc -c < "$TMP")" -le 1048576 ] || exit 0

command -v jq >/dev/null 2>&1 || exit 0
filePath="$(jq -er '.toolCall.args.TargetFile // .toolCall.args.AbsolutePath // empty' "$TMP" 2>/dev/null)" || exit 0
[ -f "$filePath" ] && [ "$(wc -c < "$filePath")" -gt 1048576 ] && exit 0
# Pipe file bytes into jq: no provider metadata, argv-size limit, or lost final newline.
set -o pipefail
BODY=$(
  if [ -f "$filePath" ]; then head -c 1048577 "$filePath"; else printf ''; fi |
  jq -Rs --slurpfile event "$TMP" --arg t "$TERM_ID" '
    if utf8bytelength > 1048576 then error("snapshot too large") else
    $event[0].toolCall as $call | $call.args as $a |
    ($a.CodeContent // $a.Content // "") as $nc |
    {type:"file_edited",terminalId:$t,toolName:($call.name // "write_to_file"),
     filePath:($a.TargetFile // $a.AbsolutePath),content:$nc,originalContent:.,newContent:$nc}
    end' 2>/dev/null
) || exit 0
printf '%s' "$BODY" > "$TMP"
curl -X POST "http://127.0.0.1:$WEBHOOK_PORT_DEV/webhook" -H "Content-Type: application/json" -d @"$TMP" --output /dev/null --silent --max-time 2 2>/dev/null || [ -n "${CODEAGENTSWARM_WEBHOOK_PORT:-}" ] || curl -X POST "http://127.0.0.1:$WEBHOOK_PORT_PROD/webhook" -H "Content-Type: application/json" -d @"$TMP" --output /dev/null --silent --max-time 2 2>/dev/null || true
exit 0
